function parseAlive(alive,side){const m=String(alive||'5V5').match(/(\d)\s*V\s*(\d)/i);let a=m?+m[1]:5,b=m?+m[2]:5;return String(side||'').startsWith('CT')?{ct:a,t:b}:{t:a,ct:b}}
function cappedMarkers(points,count,prefix){const n=Math.max(1,Math.min(count,points.length));return points.slice(0,n).map((p,i)=>[p[0],p[1],prefix+(i+1)])}
function pathD(points){return points.map((p,i)=>(i?'L':'M')+p[0]+' '+p[1]).join(' ')}
function miniBadge(x,y,text,variant='main',fill='rgba(6,10,14,.82)',stroke='rgba(255,255,255,.10)',color='#eef3f7'){
  const fs=variant==='thumb'?11:(variant==='hero'?13:12), pad=variant==='thumb'?10:12, w=Math.max(74,text.length*(variant==='thumb'?7.2:8.1)+pad*2), h=variant==='thumb'?24:28;
  return `<g><rect x="${x-w/2}" y="${y-h/2}" width="${w}" height="${h}" rx="${h/2}" fill="${fill}" stroke="${stroke}"/><text x="${x}" y="${y+fs*.34}" text-anchor="middle" fill="${color}" font-family="Arial,sans-serif" font-size="${fs}" font-weight="800">${esc(locCn(text))}</text></g>`
}
function miniMarker(x,y,label,color,variant='main'){
  const r=variant==='thumb'?10:13, ring=variant==='thumb'?16:20;
  return `<g><circle cx="${x}" cy="${y}" r="${ring}" fill="${color}" opacity=".12"/><circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/><circle cx="${x}" cy="${y}" r="${r+6}" fill="none" stroke="${color}" stroke-width="2" opacity=".34"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="#071018" font-family="monospace" font-size="${variant==='thumb'?9:10}" font-weight="900">${label}</text></g>`
}
function areaStyle(kind){return kind==='site'?{base:'#6d562f',fill:'rgba(255,173,25,.18)',stroke:'rgba(255,190,94,.72)'}:kind==='def'?{base:'#31475c',fill:'rgba(92,188,255,.12)',stroke:'rgba(135,214,255,.52)'}:kind==='cover'?{base:'#47545e',fill:'rgba(255,255,255,.08)',stroke:'rgba(255,255,255,.18)'}:{base:'#414d58',fill:'rgba(255,255,255,.06)',stroke:'rgba(255,255,255,.16)'}}
function mapAreaNode(a,variant='main'){
  const st=areaStyle(a.kind),shadow=a.pts.split(' ').map(pt=>{let [x,y]=pt.split(',').map(Number);return `${x+8},${y+10}`}).join(' ');
  return `<g><polygon points="${shadow}" fill="rgba(0,0,0,.24)"/><polygon points="${a.pts}" fill="${st.base}" opacity=".94"/><polygon points="${a.pts}" fill="${st.fill}"/><polygon points="${a.pts}" fill="none" stroke="${st.stroke}" stroke-width="2.2"/>${miniBadge(a.lx,a.ly,locCn(a.label),variant,'rgba(6,10,14,.74)','rgba(255,255,255,.08)','#f4f8fb')}</g>`
}
function boardMeta(scene,info,variant,accent){
  if(variant==='thumb') return '';
  const rows=[['MAP',mapCn(info.key)],['SITE',siteCn(info.site)],['SIDE',scene.side],['ALIVE',scene.alive],['TIMER',scene.timer]];
  const x=variant==='hero'?742:752,y=40,w=variant==='hero'?218:208,h=variant==='hero'?168:162;
  return `<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="18" fill="rgba(6,10,14,.82)" stroke="rgba(255,255,255,.10)"/>${rows.map((r,i)=>`<text x="${x+18}" y="${y+26+i*28}" fill="${i%2?accent:'#8497a6'}" font-family="monospace" font-size="12" font-weight="800">${r[0]}</text><text x="${x+92}" y="${y+26+i*28}" fill="#f2f6f9" font-family="Arial,sans-serif" font-size="14" font-weight="800">${esc(r[1])}</text>`).join('')}</g>`
}
function boardHeader(scene,info,variant,accent){
  const title=variant==='hero'?'TACTICAL MINIMAP OVERVIEW':scene.state;
  const subtitle=variant==='hero'?'专业化残局 / 站位测试界面':scene.subline;
  const titleSize=variant==='hero'?34:(variant==='thumb'?19:30);
  const boxW=variant==='hero'?438:(variant==='thumb'?262:352), boxH=variant==='hero'?104:(variant==='thumb'?80:96), x=38,y=38;
  return `<g><rect x="${x}" y="${y}" width="${boxW}" height="${boxH}" rx="18" fill="rgba(6,10,14,.84)" stroke="rgba(255,255,255,.10)"/><text x="${x+22}" y="${y+28}" fill="#9eb1bf" font-family="monospace" font-size="${variant==='thumb'?10:12}" font-weight="800">${esc(mapCn(info.key))} // ${esc(siteCn(info.site))}</text><text x="${x+22}" y="${y+60}" fill="${accent}" font-family="Arial,sans-serif" font-size="${titleSize}" font-weight="900">${esc(title)}</text><text x="${x+22}" y="${y+(variant==='thumb'?72:84)}" fill="#d0dbe3" font-family="Arial,sans-serif" font-size="${variant==='thumb'?10:12}" font-weight="700">${esc(subtitle)}</text></g>`
}
function analysisFooter(scene,info,variant){
  if(variant==='thumb') return '';
  const y=variant==='hero'?608:612,h=variant==='hero'?148:72;
  if(variant==='hero') return `<g><rect x="38" y="${y}" width="924" height="${h}" rx="22" fill="rgba(6,10,14,.82)" stroke="rgba(255,255,255,.09)"/><text x="66" y="${y+32}" fill="#ffad19" font-family="monospace" font-size="14" font-weight="900">WHAT YOU ANALYZE</text><text x="66" y="${y+66}" fill="#f2f6f9" font-family="Arial,sans-serif" font-size="24" font-weight="900">小地图站位 / 道具路线 / 交叉火力 / 残局处理</text><text x="66" y="${y+98}" fill="#9db0bf" font-family="Arial,sans-serif" font-size="14" font-weight="600">答题先看小地图，再做判断；不再只用一张实景图当背景。</text><text x="66" y="${y+126}" fill="#7f96a7" font-family="Arial,sans-serif" font-size="13" font-weight="600">Mirage · Inferno · Dust2 · Nuke · Ancient · Anubis · Vertigo · Train</text></g>`;
  return `<g><rect x="34" y="${y}" width="932" height="${h}" rx="18" fill="rgba(6,10,14,.80)" stroke="rgba(255,255,255,.08)"/><text x="56" y="${y+26}" fill="#ffad19" font-family="monospace" font-size="12" font-weight="900">已知信息</text><text x="148" y="${y+26}" fill="#d7e0e7" font-family="Arial,sans-serif" font-size="12" font-weight="700">${esc(scene.known)}</text><text x="56" y="${y+52}" fill="#5cbcff" font-family="monospace" font-size="12" font-weight="900">判断重点</text><text x="148" y="${y+52}" fill="#d7e0e7" font-family="Arial,sans-serif" font-size="12" font-weight="700">${esc(scene.focus)}</text></g>`
}
function boardLegend(info,variant){
  if(variant==='thumb') return '';
  return `<g><rect x="36" y="564" width="480" height="26" rx="13" fill="rgba(6,10,14,.70)" stroke="rgba(255,255,255,.08)"/><circle cx="58" cy="577" r="7" fill="#ffad19"/><text x="74" y="581" fill="#dce5ec" font-family="Arial,sans-serif" font-size="11" font-weight="800">T 站位</text><circle cx="146" cy="577" r="7" fill="#5cbcff"/><text x="162" y="581" fill="#dce5ec" font-family="Arial,sans-serif" font-size="11" font-weight="800">CT 站位</text><circle cx="244" cy="577" r="9" fill="#dce5ec" opacity=".16" stroke="#dce5ec"/><text x="262" y="581" fill="#dce5ec" font-family="Arial,sans-serif" font-size="11" font-weight="800">烟 / 闪</text><text x="372" y="581" fill="#8fa4b5" font-family="Arial,sans-serif" font-size="11" font-weight="700">关键区域：${esc(hintCn(info.hint))}</text></g>`
}
function tacticalBoard(scene,variant='main'){
  const info=MAP_LAYOUTS[scene.mapInfo.map]||MAP_LAYOUTS['MIRAGE'];
  const accent=scene.mapInfo.accent||'#ffad19', ct='#5cbcff';
  const counts=parseAlive(scene.alive,scene.side), tMarks=cappedMarkers(info.tSpots,Math.min(counts.t,4),'T'), ctMarks=cappedMarkers(info.ctSpots,Math.min(counts.ct,3),'CT');
  const W=1000,H=700,scale=variant==='thumb'?.56:(variant==='hero'?1:1), viewH=variant==='thumb'?420:700;
  const areas=(info.areas||[]).map(a=>mapAreaNode(a,variant)).join('');
  const routes=(info.routes||[]).map((pts,i)=>`<g><path d="${pathD(pts)}" fill="none" stroke="${i===0?accent:ct}" stroke-width="${variant==='thumb'?5:6.5}" stroke-linecap="round" stroke-dasharray="10 12" opacity=".95"/><path d="${pathD(pts)}" fill="none" stroke="${i===0?accent:ct}" stroke-width="${variant==='thumb'?12:16}" stroke-linecap="round" opacity=".10"/></g>`).join('');
  const markers=tMarks.map(([x,y,l])=>miniMarker(x,y,l,accent,variant)).join('')+ctMarks.map(([x,y,l])=>miniMarker(x,y,l,ct,variant)).join('');
  const smokes=(info.smokes||[]).map(([x,y,label])=>`<g><circle cx="${x}" cy="${y}" r="${variant==='thumb'?18:24}" fill="#dbe3ea" opacity=".16"/><circle cx="${x+13}" cy="${y+8}" r="${variant==='thumb'?12:16}" fill="#dbe3ea" opacity=".10"/>${miniBadge(x,y-26,label,variant,'rgba(6,10,14,.74)','rgba(255,255,255,.08)','#e8eff3')}</g>`).join('');
  const flash=info.flash?`<g><circle cx="${info.flash[0]}" cy="${info.flash[1]}" r="${variant==='thumb'?15:19}" fill="rgba(255,255,255,.08)" stroke="rgba(255,255,255,.48)"/><text x="${info.flash[0]}" y="${info.flash[1]+4}" text-anchor="middle" fill="#fff" font-family="monospace" font-size="${variant==='thumb'?8:10}" font-weight="900">F</text></g>`:'';
  const bomb=((scene.goal||'').includes('POST')||(scene.goal||'').includes('AFTER')||(scene.goal||'').includes('CLUTCH'))&&info.bomb&&info.bomb[0]?`<g><rect x="${info.bomb[0]-34}" y="${info.bomb[1]-16}" width="68" height="32" rx="10" fill="rgba(255,173,25,.18)" stroke="rgba(255,173,25,.58)"/><text x="${info.bomb[0]}" y="${info.bomb[1]+5}" text-anchor="middle" fill="#ffd27d" font-family="monospace" font-size="${variant==='thumb'?11:13}" font-weight="900">BOMB</text></g>`:'';
  const siteMark=`<text x="${variant==='thumb'?780:808}" y="${variant==='thumb'?496:520}" fill="rgba(255,255,255,.035)" font-family="Arial,sans-serif" font-size="${variant==='thumb'?150:190}" font-weight="900">${esc(info.siteMark)}</text>`;
  const thumbTitle=variant==='thumb'?`<g><rect x="34" y="28" width="252" height="76" rx="16" fill="rgba(6,10,14,.84)" stroke="rgba(255,255,255,.09)"/><text x="56" y="56" fill="#ffad19" font-family="monospace" font-size="11" font-weight="900">${esc(info.key)} // ${esc(info.site)}</text><text x="56" y="86" fill="#f2f6f9" font-family="Arial,sans-serif" font-size="22" font-weight="900">${esc(scene.state)}</text></g>`:'';
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${W*scale}" height="${viewH*scale}" viewBox="0 0 1000 ${viewH}"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#0a1219"/><stop offset="1" stop-color="#15212c"/></linearGradient><linearGradient id="mapg" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#0f1821"/><stop offset="1" stop-color="#121e29"/></linearGradient><pattern id="grid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="rgba(255,255,255,.028)"/></pattern><filter id="soft"><feGaussianBlur stdDeviation="20"/></filter></defs><rect width="1000" height="${viewH}" rx="28" fill="url(#bg)"/><circle cx="180" cy="118" r="150" fill="#ffad19" opacity=".09" filter="url(#soft)"/><circle cx="874" cy="116" r="168" fill="#5cbcff" opacity=".08" filter="url(#soft)"/>${variant!=='thumb'?boardHeader(scene,info,variant,accent):''}${variant!=='thumb'?boardMeta(scene,info,variant,accent):thumbTitle}<rect x="34" y="${variant==='hero'?166:168}" width="932" height="${variant==='hero'?420:390}" rx="24" fill="url(#mapg)" stroke="rgba(255,255,255,.08)"/><rect x="34" y="${variant==='hero'?166:168}" width="932" height="${variant==='hero'?420:390}" rx="24" fill="url(#grid)"/><g transform="translate(0,${variant==='thumb'?-6:38})">${siteMark}${areas}${routes}${smokes}${flash}${bomb}${markers}</g>${variant!=='thumb'?boardLegend(info,variant):''}${variant!=='thumb'?analysisFooter(scene,info,variant):''}</svg>`;
  return svgUri(svg)
}
function mapScene(scene,variant='main'){return tacticalBoard(scene,variant)}
function mapThumb(scene,label){const s=Object.assign({},scene,{state:label||scene.state,subline:scene.focus||scene.subline});return tacticalBoard(s,'thumb')}
function buildScenario(i){
  const q=QUESTIONS[i];
  const base=MAP_LIBRARY.find(m=>m.map===q.map)||MAP_LIBRARY[i%MAP_LIBRARY.length];
  const mapInfo=Object.assign({},base,{site:q.site||base.site});
  const skins=Array.from({length:5},(_,k)=>SKIN_LIBRARY[(i+k)%SKIN_LIBRARY.length]);
  const layout=MAP_LAYOUTS[mapInfo.map]||MAP_LAYOUTS['MIRAGE'];
  return {index:i+1,mapInfo,alive:q.alive,econ:q.econ,timer:q.timer,side:q.side,goal:q.goal,state:q.state,subline:q.subline,lead:q.q,known:q.known,focus:q.focus,question:q.q,skins,photo:'',photoAlt:'',thumbA:'站位摘要',thumbB:'后续处理',thumbC:(layout.thumbs&&layout.thumbs[2])||layout.hint,intelTitle:`${q.map} · ${q.site} · ${q.goal}`,intel:[`<strong>地图与局势：</strong>${q.map} ${q.site}，${q.alive}，${q.side}，${q.econ}。`,`<strong>已知信息：</strong>${q.known}`,`<strong>判断重点：</strong>${q.focus}`,`<strong>关键区域：</strong>${layout.hint}`]}
}
const TACTICAL_PACKS=QUESTIONS.map((_,i)=>buildScenario(i));
