function userVector(){let s=Array(8).fill(0);QUESTIONS.forEach((q,i)=>q.o[answers[i]].v.forEach((x,d)=>s[d]+=x));return s.map(x=>x/QUESTIONS.length)}
function sim(u,p){let ss=0,total=0;for(let i=0;i<8;i++){let w=i===7?.8:1;ss+=w*(u[i]-p.dims[i])**2;total+=w}return Math.max(45,Math.min(98.8,100-Math.sqrt(ss/total)*.7))}
function roleMeta(u){let role='Hybrid',impact='Balanced',tempo='Measured';if(u[7]>78){role='AWPer';impact='Angle control'}else if(u[6]>84){role='IGL';impact='System'}else if(u[0]>84){role='Entry';impact='Space maker';tempo='Fast'}else if(u[5]>88){role='Clutcher';impact='Late round';tempo='Calm'}else if(u[3]>90){role='Reader';impact='Timing'}else if(u[1]>92){role='Rifler';impact='Aim';tempo='Direct'}if(u[2]>86&&tempo==='Measured')tempo='Patient';return{role,impact,tempo}}
