function hdMapImagePath(map){const key=MINIMAP_IMAGES[map]||'mirage';return `./assets/maps_hd/${key}.webp`}
function mapImagePath(map){return hdMapImagePath(map)}
function overlayImage(scene){return `./assets/overlays/q${String(scene.index).padStart(2,'0')}.png`}
function focusV19Image(scene){return hdMapImagePath(scene.mapInfo.map)}
function scenarioImage(scene){return hdMapImagePath(scene.mapInfo.map)}
function scenarioFocusImage(scene){return hdMapImagePath(scene.mapInfo.map)}
function mapScene(scene,variant='main'){return hdMapImagePath(scene.mapInfo.map)}
function mapThumb(scene,label){return label==='关键区域'?focusV19Image(scene):hdMapImagePath(scene.mapInfo.map)}
function applyDirectAsset(img,url,fallback){if(!img)return;img.onerror=()=>{img.onerror=null;if(fallback&&fallback!==url)img.src=fallback};img.src=url}
function applySkinAsset(img,item){if(!img||!item)return;const url=SKIN_ASSETS[item.name];if(url){img.onerror=()=>{img.onerror=null;img.src=skinCardUri(item,'mini')};img.src=url}else img.src=skinCardUri(item,'mini')}
